double min_distance = std::numeric_limits<double>::max();

for (auto& node : m_nodes) {
    // Check if the node belongs to any road that is NOT a footway
    // The node_to_road map was populated in create_node_to_road_hashmap() 
    // specifically excluding footways.
    if (node_to_road.find(node.index_) != node_to_road.end()) {
        double dx = node.x - x;
        double dy = node.y - y;
        double distance = std::sqrt(dx * dx + dy * dy);

        if (distance < min_distance) {
            min_distance = distance;
            closest_node = &node;
        }
    }
}

return closest_node;

